package com.airesumebuilder.feature.admin.service;import static org.assertj.core.api.Assertions.assertThatThrownBy;import static org.mockito.Mockito.*;import com.airesumebuilder.common.exception.ValidationException;import com.airesumebuilder.feature.admin.repository.AdminRepository;import com.airesumebuilder.feature.admin.service.AdminService.*;import java.time.Instant;import org.junit.jupiter.api.Test;
class AdminServiceTest{@Test void rejectsInvalidRoleBeforeWriting(){AdminRepository r=mock(AdminRepository.class);assertThatThrownBy(()->new AdminService(r).role("admin@test",2,new ChangeRequest("owner"))).isInstanceOf(ValidationException.class);verify(r,never()).update(anyString(),anyLong(),anyString(),anyString(),anyString());}@Test void preventsSelfDemotion(){AdminRepository r=mock(AdminRepository.class);when(r.email(2)).thenReturn("admin@test");assertThatThrownBy(()->new AdminService(r).role("admin@test",2,new ChangeRequest("user"))).isInstanceOf(ValidationException.class);}}
